-- Syllabus edition for this career.
insert into public.syllabus_editions (contest_name,role_name,contest_year,source_id)
select 'Polícia Civil de Minas Gerais','Técnico-Assistente da Polícia Civil e de Atividades Governamentais (TPAG) - Auxiliar de Perícia',2025,(select id from public.content_sources where url=$q$https://www.cebraspe.org.br/concursos/pc_mg_25_tpag/prova_objetiva_eixo_geral$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Civil de Minas Gerais' and role_name='Técnico-Assistente da Polícia Civil e de Atividades Governamentais (TPAG) - Auxiliar de Perícia' and contest_year=2025
);

-- Discipline breakdown derived directly from the prova's own eixo/section
-- headers and item content.
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil de Minas Gerais' and role_name='Técnico-Assistente da Polícia Civil e de Atividades Governamentais (TPAG) - Auxiliar de Perícia' and contest_year=2025
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de texto (Texto CG1A1), emprego de conjunções, substituição de expressões e locuções verbais sem prejuízo da correção gramatical e da coerência (itens 1 a 6 - Eixo Geral).'),
  ('Noções de Informática','Ferramentas colaborativas em nuvem, fórmulas e referências de células no Microsoft Excel, estratégias de backup, modelos de computação em nuvem (IaaS/PaaS/SaaS) e ameaças de segurança na Internet, como phishing (itens 7 a 11 - Eixo Geral).'),
  ('Raciocínio Lógico-Matemático','Sequências e progressões, regra de três e produtividade, lógica proposicional (implicação e negação) e probabilidade (itens 12 a 15 - Eixo Geral).'),
  ('Direitos Humanos','Afirmação histórica, universalidade e indivisibilidade dos direitos humanos, responsabilidade do Estado, políticas públicas, a Constituição Federal de 1988 e tratados internacionais de direitos humanos, incluindo o Pacto de São José da Costa Rica (itens 16 a 22 - Eixo Legislação).'),
  ('Legislação Institucional da PCMG','Lei Orgânica da Polícia Civil do Estado de Minas Gerais (Lei estadual nº 5.406/1969 e Lei Complementar estadual nº 129/2013), Código de Conduta Ética do Agente Público (Decreto estadual nº 46.644/2014), Lei estadual nº 15.301/2004 (carreiras do Grupo de Atividades de Defesa Social) e Estatuto dos Funcionários Públicos Civis do Estado de Minas Gerais (Lei estadual nº 869/1952) (itens 23 a 30 - Eixo Legislação).'),
  ('Conhecimentos Específicos - Auxiliar de Perícia','Procedimentos operacionais de preservação, remoção e movimentação de corpos em cena de crime e no IML, coleta de amostras para exame toxicológico e histopatológico, biossegurança, gerenciamento e descarte de resíduos de serviços de saúde, e limites éticos e legais da necropsia (itens 31 a 60 - Eixo Específico).')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2025,1,$q$Língua Portuguesa$q$,$q$O texto CG1A1 destaca, no contexto da pandemia de covid-19, o papel relevante exercido A por cientistas e jornalistas especializados em saúde. B pelos profissionais de saúde, em geral. C pelos médicos patologistas. D pela OMS.$q$,$q$O texto CG1A1 destaca, no contexto da pandemia de covid-19, o papel relevante exercido A por cientistas e jornalistas especializados em saúde. B pelos profissionais de saúde, em geral. C pelos médicos patologistas. D pela OMS.$q$,'C',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 (base textual da prova) para contextualização completa.$q$),
(2025,2,$q$Língua Portuguesa$q$,$q$De acordo com as ideias veiculadas no texto CG1A1, as necropsias realizadas durante a pandemia de covid-19 A acarretaram a demora da OMS em reconhecer a pandemia. B contribuíram para a identificação da nova doença e o entendimento de suas peculiaridades. C revelaram tratar-se de mais uma endemia desencadeada por um vírus respiratório originário da Ásia. D reforçaram as incertezas já existentes sobre o novo vírus.$q$,$q$De acordo com as ideias veiculadas no texto CG1A1, as necropsias realizadas durante a pandemia de covid-19 A acarretaram a demora da OMS em reconhecer a pandemia. B contribuíram para a identificação da nova doença e o entendimento de suas peculiaridades. C revelaram tratar-se de mais uma endemia desencadeada por um vírus respiratório originário da Ásia. D reforçaram as incertezas já existentes sobre o novo vírus.$q$,'B',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); enunciado reconstruído por de-interleaving mecânico de duas colunas de PDF entrelaçadas com o item 6 (mesma extração), sem invenção de conteúdo. Gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 para contextualização completa.$q$),
(2025,3,$q$Língua Portuguesa$q$,$q$No trecho “Muitos ‘especialistas’ fizeram previsões e ofereceram orientações categóricas” (segundo parágrafo do texto CG1A1), o emprego das aspas na palavra ‘especialistas’ A reforça o grau de conhecimento dos membros da OMS sobre a covid-19. B sugere a intenção irônica do autor do texto em sua referência aos que fizeram previsões e ofereceram orientações categóricas a respeito da covid-19. C visa destacar a importância dos especialistas no contexto da pandemia de covid-19 e das críticas dirigidas à OMS em razão de sua demora e hesitação no reconhecimento da pandemia. D indica que o termo foi empregado de forma genérica.$q$,$q$No trecho “Muitos ‘especialistas’ fizeram previsões e ofereceram orientações categóricas” (segundo parágrafo do texto CG1A1), o emprego das aspas na palavra ‘especialistas’ A reforça o grau de conhecimento dos membros da OMS sobre a covid-19. B sugere a intenção irônica do autor do texto em sua referência aos que fizeram previsões e ofereceram orientações categóricas a respeito da covid-19. C visa destacar a importância dos especialistas no contexto da pandemia de covid-19 e das críticas dirigidas à OMS em razão de sua demora e hesitação no reconhecimento da pandemia. D indica que o termo foi empregado de forma genérica.$q$,'B',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 para contextualização completa.$q$),
(2025,4,$q$Língua Portuguesa$q$,$q$No trecho “Graças às informações comparativas das autópsias, foi possível identificar a doença” (último parágrafo do texto CG1A1), a expressão “Graças às” poderia ser substituída, sem prejuízo da correção gramatical e da coerência das ideias do texto, por A Com o auxílio das. B Em que pesem as. C Em detrimento das. D Devido as.$q$,$q$No trecho “Graças às informações comparativas das autópsias, foi possível identificar a doença” (último parágrafo do texto CG1A1), a expressão “Graças às” poderia ser substituída, sem prejuízo da correção gramatical e da coerência das ideias do texto, por A Com o auxílio das. B Em que pesem as. C Em detrimento das. D Devido as.$q$,'A',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 para contextualização completa.$q$),
(2025,5,$q$Língua Portuguesa$q$,$q$No trecho “A valorização global do esforço dos profissionais de saúde foi generalizada, porém, entre tantas categorias homenageadas, é crucial destacar o papel dos médicos patologistas” (terceiro parágrafo do texto CG1A1), o vocábulo “porém” classifica-se como conjunção que expressa A adição. B explicação. C conclusão. D contraste.$q$,$q$No trecho “A valorização global do esforço dos profissionais de saúde foi generalizada, porém, entre tantas categorias homenageadas, é crucial destacar o papel dos médicos patologistas” (terceiro parágrafo do texto CG1A1), o vocábulo “porém” classifica-se como conjunção que expressa A adição. B explicação. C conclusão. D contraste.$q$,'D',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 para contextualização completa.$q$),
(2025,6,$q$Língua Portuguesa$q$,$q$No trecho “foram reforçadas a necessidade de um maior controle sanitário e a importância de uma análise patológica minuciosa” (último parágrafo do texto CG1A1), a locução verbal “foram reforçadas” poderia ser substituída, sem prejuízo da correção gramatical e do sentido original do texto, por A haviam reforçado. B reforçou. C era reforçado. D reforçaram-se.$q$,$q$No trecho “foram reforçadas a necessidade de um maior controle sanitário e a importância de uma análise patológica minuciosa” (último parágrafo do texto CG1A1), a locução verbal “foram reforçadas” poderia ser substituída, sem prejuízo da correção gramatical e do sentido original do texto, por A haviam reforçado. B reforçou. C era reforçado. D reforçaram-se.$q$,'D',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); enunciado reconstruído por de-interleaving mecânico de duas colunas de PDF entrelaçadas com o item 2 (mesma extração), sem invenção de conteúdo. Gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). Depende do Texto CG1A1 para contextualização completa.$q$),
(2025,7,$q$Noções de Informática$q$,$q$Suponha que uma equipe multiprofissional de uma instituição pública esteja elaborando um protocolo técnico-operacional e necessite produzir, revisar e manter versões atualizadas do documento, com registro histórico de alterações, possibilidade de edição simultânea e acesso controlado por diferentes profissionais, a partir de dispositivos conectados à Internet. Considerando essa situação hipotética e as ferramentas colaborativas disponíveis, assinale a opção em que é apresentado o recurso que atende integralmente às necessidades da equipe. A repositório indexado para pesquisa B correio eletrônico corporativo C rede corporativa com grupos fechados D editor de textos colaborativo em nuvem$q$,$q$Suponha que uma equipe multiprofissional de uma instituição pública esteja elaborando um protocolo técnico-operacional e necessite produzir, revisar e manter versões atualizadas do documento, com registro histórico de alterações, possibilidade de edição simultânea e acesso controlado por diferentes profissionais, a partir de dispositivos conectados à Internet. Considerando essa situação hipotética e as ferramentas colaborativas disponíveis, assinale a opção em que é apresentado o recurso que atende integralmente às necessidades da equipe. A repositório indexado para pesquisa B correio eletrônico corporativo C rede corporativa com grupos fechados D editor de textos colaborativo em nuvem$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,8,$q$Noções de Informática$q$,$q$Em certa planilha do Microsoft Excel, reproduzida na figura a seguir, a célula B1 contém um fator de ajuste que deve ser aplicado aos valores das células A2, A3 e A4. Deseja-se inserir, em B2, uma fórmula que possa ser copiada verticalmente, mantendo fixa a linha do fator de ajuste e permitindo a variação da linha dos valores. Considerando o comportamento das referências de células no Excel, assinale a opção em que é corretamente apresentada a fórmula que atende ao objetivo descrito na situação hipotética precedente. A =$A2*B1 B =A$2*B$1 C =$A$2*B1 D =A2*B$1$q$,$q$Em certa planilha do Microsoft Excel, reproduzida na figura a seguir, a célula B1 contém um fator de ajuste que deve ser aplicado aos valores das células A2, A3 e A4. Deseja-se inserir, em B2, uma fórmula que possa ser copiada verticalmente, mantendo fixa a linha do fator de ajuste e permitindo a variação da linha dos valores. Considerando o comportamento das referências de células no Excel, assinale a opção em que é corretamente apresentada a fórmula que atende ao objetivo descrito na situação hipotética precedente. A =$A2*B1 B =A$2*B$1 C =$A$2*B1 D =A2*B$1$q$,'D',1,'under_review',false,true,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6). O enunciado referencia uma figura/planilha não reproduzível em texto puro; revisão de contexto necessária antes de exibição.$q$),
(2025,9,$q$Noções de Informática$q$,$q$Considere que uma organização pública mantenha sistemas informatizados que armazenam documentos digitais oficiais, imagens e registros administrativos. Nessa situação, para assegurar a recuperação eficiente dos dados após falha lógica decorrente de alterações indevidas nos arquivos, com redução do volume diário de armazenamento e preservação de versões anteriores, a estratégia de backup de arquivos que se deve adotar é A realizar backups por espelhamento em tempo real. B realizar backups por sincronização em nuvem. C combinar backups incrementais a backups completos periódicos. D realizar backups diferenciais sem base completa.$q$,$q$Considere que uma organização pública mantenha sistemas informatizados que armazenam documentos digitais oficiais, imagens e registros administrativos. Nessa situação, para assegurar a recuperação eficiente dos dados após falha lógica decorrente de alterações indevidas nos arquivos, com redução do volume diário de armazenamento e preservação de versões anteriores, a estratégia de backup de arquivos que se deve adotar é A realizar backups por espelhamento em tempo real. B realizar backups por sincronização em nuvem. C combinar backups incrementais a backups completos periódicos. D realizar backups diferenciais sem base completa.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,10,$q$Noções de Informática$q$,$q$Um instituto médico-legal deseja disponibilizar um sistema interno de gestão pericial que possa ser acessado remotamente por suas unidades regionais. A instituição pretende executar aplicações próprias desenvolvidas internamente, manter controle total sobre o sistema operacional e as configurações do ambiente, e evitar a aquisição e manutenção direta de servidores físicos, delegando a infraestrutura subjacente ao provedor do serviço. Considerando a situação hipotética precedente e os modelos de computação em nuvem, assinale a opção em que é corretamente apresentada a solução que atende integralmente às necessidades da instituição. A software como serviço B plataforma como serviço C infraestrutura como serviço D armazenamento em nuvem como serviço$q$,$q$Um instituto médico-legal deseja disponibilizar um sistema interno de gestão pericial que possa ser acessado remotamente por suas unidades regionais. A instituição pretende executar aplicações próprias desenvolvidas internamente, manter controle total sobre o sistema operacional e as configurações do ambiente, e evitar a aquisição e manutenção direta de servidores físicos, delegando a infraestrutura subjacente ao provedor do serviço. Considerando a situação hipotética precedente e os modelos de computação em nuvem, assinale a opção em que é corretamente apresentada a solução que atende integralmente às necessidades da instituição. A software como serviço B plataforma como serviço C infraestrutura como serviço D armazenamento em nuvem como serviço$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,11,$q$Noções de Informática$q$,$q$Um técnico de laboratório recebe em seu correio eletrônico institucional uma mensagem que aparenta ter sido enviada pelo setor de TI da organização, solicitando a atualização da senha de acesso aos sistemas internos por meio de um link fornecido na própria mensagem. Ao acessar o link, o técnico é direcionado a uma página visualmente semelhante ao portal oficial da instituição e, nela, insere seu usuário e sua senha, sem realizar download, instalação ou execução de qualquer arquivo, programa ou extensão. Posteriormente, identifica-se, nos registros de acesso corporativos, que as credenciais informadas pelo técnico foram utilizadas por terceiros sem autorização para acessar sistemas internos da instituição. Considerando a situação hipotética apresentada e conceitos de segurança na Internet, assinale a opção em que é corretamente apresentada a ameaça caracterizada no cenário narrado. A spyware de monitoramento B malware de negação de serviço C phishing direcionado D vírus autorreplicante por execução local$q$,$q$Um técnico de laboratório recebe em seu correio eletrônico institucional uma mensagem que aparenta ter sido enviada pelo setor de TI da organização, solicitando a atualização da senha de acesso aos sistemas internos por meio de um link fornecido na própria mensagem. Ao acessar o link, o técnico é direcionado a uma página visualmente semelhante ao portal oficial da instituição e, nela, insere seu usuário e sua senha, sem realizar download, instalação ou execução de qualquer arquivo, programa ou extensão. Posteriormente, identifica-se, nos registros de acesso corporativos, que as credenciais informadas pelo técnico foram utilizadas por terceiros sem autorização para acessar sistemas internos da instituição. Considerando a situação hipotética apresentada e conceitos de segurança na Internet, assinale a opção em que é corretamente apresentada a ameaça caracterizada no cenário narrado. A spyware de monitoramento B malware de negação de serviço C phishing direcionado D vírus autorreplicante por execução local$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,12,$q$Raciocínio Lógico-Matemático$q$,$q$Um perito criminal percebe um padrão deixado por um criminoso nos locais dos crimes: os números de objetos furtados por ele correspondem ao número de diagonais em polígonos regulares, que sempre aumenta ou diminui na mesma quantidade. No primeiro local investigado, foram 2 objetos furtados; no segundo, foram 20; no terceiro, foram 9; no quarto, foram 35; no quinto, foram 20; e assim por diante. Seguindo de forma estrita a lei de formação apresentada na situação hipotética precedente, assinale a opção que indica o polígono regular associado à sétima cena do crime. A icosaedro B decágono C tetradecágono D octógono$q$,$q$Um perito criminal percebe um padrão deixado por um criminoso nos locais dos crimes: os números de objetos furtados por ele correspondem ao número de diagonais em polígonos regulares, que sempre aumenta ou diminui na mesma quantidade. No primeiro local investigado, foram 2 objetos furtados; no segundo, foram 20; no terceiro, foram 9; no quarto, foram 35; no quinto, foram 20; e assim por diante. Seguindo de forma estrita a lei de formação apresentada na situação hipotética precedente, assinale a opção que indica o polígono regular associado à sétima cena do crime. A icosaedro B decágono C tetradecágono D octógono$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,13,$q$Raciocínio Lógico-Matemático$q$,$q$Suponha que 5 peritos, trabalhando no mesmo ritmo, consigam produzir 20 relatórios de perícia, de mesmo formato, em 8 horas. Se um dos peritos afastar-se do trabalho devido a licença-médica, a equipe reduzida, trabalhando no mesmo ritmo, conseguirá produzir 26 relatórios, no mesmo formato, no período de A 13 horas. B 10 horas. C 10 horas e 24 minutos. D 8 horas e 19 minutos.$q$,$q$Suponha que 5 peritos, trabalhando no mesmo ritmo, consigam produzir 20 relatórios de perícia, de mesmo formato, em 8 horas. Se um dos peritos afastar-se do trabalho devido a licença-médica, a equipe reduzida, trabalhando no mesmo ritmo, conseguirá produzir 26 relatórios, no mesmo formato, no período de A 13 horas. B 10 horas. C 10 horas e 24 minutos. D 8 horas e 19 minutos.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,14,$q$Raciocínio Lógico-Matemático$q$,$q$Durante interrogatório de um suspeito, a delegada analisa a veracidade das afirmações apresentadas. No contexto do interrogatório, ela sabe que é logicamente falsa a seguinte proposição composta: “Se o álibi do suspeito é verdadeiro, então o suspeito estava no cinema.”. Considerando as condições descritas nessa situação hipotética, assinale a opção que corresponde corretamente a uma proposição composta logicamente verdadeira que pode ser concluída pela delegada. A “O álibi do suspeito não é verdadeiro e ele não estava no cinema.” B “O álibi do suspeito é verdadeiro e ele estava no cinema.” C “O álibi do suspeito não é verdadeiro e ele estava no cinema.” D “O álibi do suspeito é verdadeiro e ele não estava no cinema.”$q$,$q$Durante interrogatório de um suspeito, a delegada analisa a veracidade das afirmações apresentadas. No contexto do interrogatório, ela sabe que é logicamente falsa a seguinte proposição composta: “Se o álibi do suspeito é verdadeiro, então o suspeito estava no cinema.”. Considerando as condições descritas nessa situação hipotética, assinale a opção que corresponde corretamente a uma proposição composta logicamente verdadeira que pode ser concluída pela delegada. A “O álibi do suspeito não é verdadeiro e ele não estava no cinema.” B “O álibi do suspeito é verdadeiro e ele estava no cinema.” C “O álibi do suspeito não é verdadeiro e ele estava no cinema.” D “O álibi do suspeito é verdadeiro e ele não estava no cinema.”$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,15,$q$Raciocínio Lógico-Matemático$q$,$q$Uma equipe especial com quatro peritos será montada para examinar uma cena de crime. O delegado tem, à sua disposição, um grupo de 13 peritos, formado por 8 mulheres e 5 homens. Sabendo que, na situação hipotética apresentada, serão sorteados aleatoriamente quatro peritos daquele grupo para compor a equipe, assinale a opção que corresponde à probabilidade de que o grupo tenha pelo menos 2 peritos homens. A 56/143 B 70/143 C 73/143 D 129/143$q$,$q$Uma equipe especial com quatro peritos será montada para examinar uma cena de crime. O delegado tem, à sua disposição, um grupo de 13 peritos, formado por 8 mulheres e 5 homens. Sabendo que, na situação hipotética apresentada, serão sorteados aleatoriamente quatro peritos daquele grupo para compor a equipe, assinale a opção que corresponde à probabilidade de que o grupo tenha pelo menos 2 peritos homens. A 56/143 B 70/143 C 73/143 D 129/143$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Geral, fileId 1gwS_Lo5uF3rZXygH-L-0cxhHKAv8DXiR); gabarito conferido em Gabarito definitivo Eixo Geral (fileId 16WodS26L8GuJnsGBIkaK-hI29mCO87B6).$q$),
(2025,16,$q$Direitos Humanos$q$,$q$O Pacto de São José da Costa Rica visa A garantir o direito ao meio ambiente ecologicamente equilibrado. B assegurar expressamente os direitos dos povos indígenas. C garantir o direito de todos ao acesso às novas tecnologias. D assegurar o reconhecimento dos direitos essenciais da pessoa humana.$q$,$q$O Pacto de São José da Costa Rica visa A garantir o direito ao meio ambiente ecologicamente equilibrado. B assegurar expressamente os direitos dos povos indígenas. C garantir o direito de todos ao acesso às novas tecnologias. D assegurar o reconhecimento dos direitos essenciais da pessoa humana.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (tratado internacional) ainda não conferida individualmente na fonte oficial - aguardando revisão item a item antes de content_status=active.$q$),
(2025,17,$q$Direitos Humanos$q$,$q$Assinale a opção correta no que diz respeito à afirmação histórica dos direitos humanos. A A existência dos direitos humanos é resultado da atuação autônoma dos Estados, sem relação direta com revoluções ou reivindicações populares. B O reconhecimento dos direitos humanos ocorreu de maneira simultânea e positivada em todos os países europeus a partir da Declaração Universal dos Direitos Humanos de 1948. C A existência de direitos humanos somente pôde ser reconhecida após sua positivação em tratados internacionais, inexistindo proteção à dignidade humana antes do século XX. D A afirmação histórica dos direitos humanos decorre de um processo contínuo e cumulativo, no qual esses direitos foram sendo reconhecidos gradativamente, em resposta às lutas sociais e transformações políticas ao longo do tempo.$q$,$q$Assinale a opção correta no que diz respeito à afirmação histórica dos direitos humanos. A A existência dos direitos humanos é resultado da atuação autônoma dos Estados, sem relação direta com revoluções ou reivindicações populares. B O reconhecimento dos direitos humanos ocorreu de maneira simultânea e positivada em todos os países europeus a partir da Declaração Universal dos Direitos Humanos de 1948. C A existência de direitos humanos somente pôde ser reconhecida após sua positivação em tratados internacionais, inexistindo proteção à dignidade humana antes do século XX. D A afirmação histórica dos direitos humanos decorre de um processo contínuo e cumulativo, no qual esses direitos foram sendo reconhecidos gradativamente, em resposta às lutas sociais e transformações políticas ao longo do tempo.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial - aguardando revisão item a item antes de content_status=active.$q$),
(2025,18,$q$Direitos Humanos$q$,$q$Os direitos humanos A surgiram no Brasil com a promulgação da Constituição Federal de 1988 (CF), inexistindo qualquer norma protetiva a eles antes desse marco histórico. B caracterizam-se pela universalidade, indivisibilidade e historicidade, sendo reconhecidos a todas as pessoas. C confundem-se com os direitos fundamentais, sendo sua aplicação restrita ao plano internacional. D são prerrogativas concedidas exclusivamente pelo Estado, por isso este pode restringi-los livremente conforme a sua conveniência.$q$,$q$Os direitos humanos A surgiram no Brasil com a promulgação da Constituição Federal de 1988 (CF), inexistindo qualquer norma protetiva a eles antes desse marco histórico. B caracterizam-se pela universalidade, indivisibilidade e historicidade, sendo reconhecidos a todas as pessoas. C confundem-se com os direitos fundamentais, sendo sua aplicação restrita ao plano internacional. D são prerrogativas concedidas exclusivamente pelo Estado, por isso este pode restringi-los livremente conforme a sua conveniência.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial - aguardando revisão item a item antes de content_status=active.$q$),
(2025,19,$q$Direitos Humanos$q$,$q$Assinale a opção correta a respeito dos direitos humanos e da responsabilidade do Estado. A O Estado pode ser responsabilizado por omissões decorrentes de violações de direitos humanos, inclusive quando praticadas por particulares. B A responsabilidade internacional do Estado por violações de direitos humanos exige, necessariamente, a comprovação de dolo ou culpa grave de seus agentes públicos. C A responsabilidade do Estado por violações de direitos humanos restringe-se aos direitos civis e políticos, não alcançando direitos econômicos, sociais e culturais. D O Estado somente pode ser responsabilizado por violações de direitos humanos quando houver ação direta de seus agentes, sendo inaplicável a responsabilização em casos de omissão estatal.$q$,$q$Assinale a opção correta a respeito dos direitos humanos e da responsabilidade do Estado. A O Estado pode ser responsabilizado por omissões decorrentes de violações de direitos humanos, inclusive quando praticadas por particulares. B A responsabilidade internacional do Estado por violações de direitos humanos exige, necessariamente, a comprovação de dolo ou culpa grave de seus agentes públicos. C A responsabilidade do Estado por violações de direitos humanos restringe-se aos direitos civis e políticos, não alcançando direitos econômicos, sociais e culturais. D O Estado somente pode ser responsabilizado por violações de direitos humanos quando houver ação direta de seus agentes, sendo inaplicável a responsabilização em casos de omissão estatal.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial - aguardando revisão item a item antes de content_status=active.$q$),
(2025,20,$q$Direitos Humanos$q$,$q$Considerando que as políticas públicas em direitos humanos no Brasil estruturam-se a partir da CF e de instrumentos normativos e programáticos voltados à promoção e à proteção da dignidade da pessoa humana, assinale a opção correta. A As políticas públicas em direitos humanos no Brasil possuem como fundamento constitucional a dignidade da pessoa humana. B O Programa Nacional de Direitos Humanos, como política pública estruturada, limita-se à promoção dos direitos civis e políticos, sendo os direitos econômicos, sociais e culturais objeto exclusivo de políticas setoriais específicas. C A proteção dos direitos humanos compete exclusivamente à União. D O Programa Nacional de Direitos Humanos foi instituído no ordenamento jurídico brasileiro por decreto com hierarquia constitucional e força vinculante equivalente à de emenda constitucional.$q$,$q$Considerando que as políticas públicas em direitos humanos no Brasil estruturam-se a partir da CF e de instrumentos normativos e programáticos voltados à promoção e à proteção da dignidade da pessoa humana, assinale a opção correta. A As políticas públicas em direitos humanos no Brasil possuem como fundamento constitucional a dignidade da pessoa humana. B O Programa Nacional de Direitos Humanos, como política pública estruturada, limita-se à promoção dos direitos civis e políticos, sendo os direitos econômicos, sociais e culturais objeto exclusivo de políticas setoriais específicas. C A proteção dos direitos humanos compete exclusivamente à União. D O Programa Nacional de Direitos Humanos foi instituído no ordenamento jurídico brasileiro por decreto com hierarquia constitucional e força vinculante equivalente à de emenda constitucional.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial - aguardando revisão item a item antes de content_status=active.$q$),
(2025,21,$q$Direitos Humanos$q$,$q$A CF é reconhecida por sua centralidade na proteção dos direitos humanos no Brasil. A esse respeito, assinale a opção correta. A A CF admite a suspensão definitiva dos direitos fundamentais em situações excepcionais. B A CF estabelece que as normas definidoras dos direitos e garantias fundamentais tenham aplicação imediata. C A aplicação dos direitos fundamentais previstos na CF tem caráter apenas programático, dependendo sempre de lei posterior para produzir efeitos. D Os direitos fundamentais previstos na CF aplicam-se exclusivamente aos cidadãos brasileiros, não alcançando os estrangeiros residentes no país.$q$,$q$A CF é reconhecida por sua centralidade na proteção dos direitos humanos no Brasil. A esse respeito, assinale a opção correta. A A CF admite a suspensão definitiva dos direitos fundamentais em situações excepcionais. B A CF estabelece que as normas definidoras dos direitos e garantias fundamentais tenham aplicação imediata. C A aplicação dos direitos fundamentais previstos na CF tem caráter apenas programático, dependendo sempre de lei posterior para produzir efeitos. D Os direitos fundamentais previstos na CF aplicam-se exclusivamente aos cidadãos brasileiros, não alcançando os estrangeiros residentes no país.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (art. 5º, §1º, CF/1988) ainda não conferida individualmente no planalto.gov.br - aguardando revisão item a item antes de content_status=active.$q$),
(2025,22,$q$Direitos Humanos$q$,$q$A CF disciplina a relação entre o direito interno brasileiro e os tratados internacionais de direitos humanos, estabelecendo regras específicas para sua incorporação e eficácia. À luz dessas disposições, assinale a opção correta. A Os direitos e garantias expressos na CF não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte. B Os tratados internacionais de direitos humanos só produzem efeitos no ordenamento jurídico brasileiro após a sua promulgação por meio de lei complementar. C Todos os tratados internacionais de direitos humanos, em razão da relevância da matéria, integram automaticamente o rol de direitos fundamentais previstos no art. 5.º da CF. D Os tratados internacionais de direitos humanos que não observarem o rito qualificado de aprovação previsto na CF não produzem efeitos jurídicos no Brasil.$q$,$q$A CF disciplina a relação entre o direito interno brasileiro e os tratados internacionais de direitos humanos, estabelecendo regras específicas para sua incorporação e eficácia. À luz dessas disposições, assinale a opção correta. A Os direitos e garantias expressos na CF não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte. B Os tratados internacionais de direitos humanos só produzem efeitos no ordenamento jurídico brasileiro após a sua promulgação por meio de lei complementar. C Todos os tratados internacionais de direitos humanos, em razão da relevância da matéria, integram automaticamente o rol de direitos fundamentais previstos no art. 5.º da CF. D Os tratados internacionais de direitos humanos que não observarem o rito qualificado de aprovação previsto na CF não produzem efeitos jurídicos no Brasil.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (art. 5º, §2º, CF/1988) ainda não conferida individualmente no planalto.gov.br - aguardando revisão item a item antes de content_status=active.$q$),
(2025,23,$q$Legislação Institucional da PCMG$q$,$q$De acordo com a Lei Orgânica da Polícia Civil do Estado de Minas Gerais (Lei estadual n.º 5.406/1969 e Lei Complementar estadual n.º 129/2013), a chefia da PCMG deve ser exercida por A secretário de estado de justiça e segurança pública, de forma automática. B servidor efetivo da polícia civil, eleito pelos integrantes da instituição. C delegado de polícia de carreira, nomeado pelo governador do estado. D oficial da polícia militar, escolhido pelo governador do estado.$q$,$q$De acordo com a Lei Orgânica da Polícia Civil do Estado de Minas Gerais (Lei estadual n.º 5.406/1969 e Lei Complementar estadual n.º 129/2013), a chefia da PCMG deve ser exercida por A secretário de estado de justiça e segurança pública, de forma automática. B servidor efetivo da polícia civil, eleito pelos integrantes da instituição. C delegado de polícia de carreira, nomeado pelo governador do estado. D oficial da polícia militar, escolhido pelo governador do estado.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Lei estadual nº 5.406/1969 e Lei Complementar estadual nº 129/2013) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,24,$q$Legislação Institucional da PCMG$q$,$q$Considerando o disposto na Lei Orgânica da Polícia Civil do Estado de Minas Gerais (Lei estadual n.º 5.406/1969) bem como as alterações promovidas pela Lei Complementar estadual n.º 129/2013, assinale a opção correta acerca da estrutura e do exercício das funções de polícia judiciária no âmbito da PCMG. A A apuração das infrações penais comuns, de incumbência da polícia judiciária, compete à polícia civil apenas quando inexistir atuação prévia da polícia militar ou de outro órgão de segurança pública. B As funções de polícia judiciária são exercidas de forma descentralizada e autônoma por todos os servidores policiais, independentemente de hierarquia funcional. C A PCMG, sob a direção superior exercida pelo chefe da polícia civil, exerce a função de polícia judiciária, cabendo-lhe a apuração, no território do estado, de infrações penais, observados os princípios da hierarquia e da disciplina. D A atividade de polícia judiciária é exercida exclusivamente pelos delegados de polícia, sendo vedada a participação de outros cargos da carreira policial civil.$q$,$q$Considerando o disposto na Lei Orgânica da Polícia Civil do Estado de Minas Gerais (Lei estadual n.º 5.406/1969) bem como as alterações promovidas pela Lei Complementar estadual n.º 129/2013, assinale a opção correta acerca da estrutura e do exercício das funções de polícia judiciária no âmbito da PCMG. A A apuração das infrações penais comuns, de incumbência da polícia judiciária, compete à polícia civil apenas quando inexistir atuação prévia da polícia militar ou de outro órgão de segurança pública. B As funções de polícia judiciária são exercidas de forma descentralizada e autônoma por todos os servidores policiais, independentemente de hierarquia funcional. C A PCMG, sob a direção superior exercida pelo chefe da polícia civil, exerce a função de polícia judiciária, cabendo-lhe a apuração, no território do estado, de infrações penais, observados os princípios da hierarquia e da disciplina. D A atividade de polícia judiciária é exercida exclusivamente pelos delegados de polícia, sendo vedada a participação de outros cargos da carreira policial civil.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,25,$q$Legislação Institucional da PCMG$q$,$q$De acordo com os dispositivos legais que disciplinam a organização da Polícia Civil de Minas Gerais, assinale opção correta. A A Superintendência de Polícia Técnico-Científica será dirigida preferencialmente por médico-legista ou perito criminal, em atividade e no último nível da carreira, admitida a direção por delegado de polícia, desde que conte com, no mínimo, quinze anos de efetivo exercício. B As delegacias de polícia civil, de âmbito territorial e de atuação especializada, devem ser dirigidas por delegados de polícia de carreira, enquanto as delegacias regionais e as divisões de polícia especializada devem ser dirigidas por delegados de polícia de, no mínimo, nível especial. C A chefia da PCMG e a chefia adjunta da PCMG, funções comissionadas de livre exoneração, somente podem ser exercidas por delegados de polícia em atividade, do nível final da carreira, que possuam, no mínimo, 25 anos de efetivo serviço. D Em caso de afastamento ou impedimento eventual do chefe adjunto, o chefe da PCMG será substituído, automaticamente, pelo chefe de gabinete da instituição.$q$,$q$De acordo com os dispositivos legais que disciplinam a organização da Polícia Civil de Minas Gerais, assinale opção correta. A A Superintendência de Polícia Técnico-Científica será dirigida preferencialmente por médico-legista ou perito criminal, em atividade e no último nível da carreira, admitida a direção por delegado de polícia, desde que conte com, no mínimo, quinze anos de efetivo exercício. B As delegacias de polícia civil, de âmbito territorial e de atuação especializada, devem ser dirigidas por delegados de polícia de carreira, enquanto as delegacias regionais e as divisões de polícia especializada devem ser dirigidas por delegados de polícia de, no mínimo, nível especial. C A chefia da PCMG e a chefia adjunta da PCMG, funções comissionadas de livre exoneração, somente podem ser exercidas por delegados de polícia em atividade, do nível final da carreira, que possuam, no mínimo, 25 anos de efetivo serviço. D Em caso de afastamento ou impedimento eventual do chefe adjunto, o chefe da PCMG será substituído, automaticamente, pelo chefe de gabinete da instituição.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,26,$q$Legislação Institucional da PCMG$q$,$q$Com base no Decreto estadual n.º 46.644/2014, que dispõe sobre o Código de Conduta Ética do Agente Público e da Alta Administração Estadual de Minas Gerais, assinale a opção correta. A É vedado ao agente público permitir que interesses particulares prevaleçam sobre o interesse público, bem como participar de qualquer atividade que possa significar conflito de interesse em relação à atividade pública que exerce. B A observância das normas éticas previstas no referido decreto é facultativa, constituindo mera recomendação de boas práticas administrativas. C A atuação das comissões de ética limita-se à aplicação de sanções disciplinares, sendo-lhes vedada a função orientadora ou preventiva. D O referido código de conduta ética aplica-se exclusivamente aos ocupantes de cargos de direção superior, não alcançando servidores efetivos nem empregados públicos.$q$,$q$Com base no Decreto estadual n.º 46.644/2014, que dispõe sobre o Código de Conduta Ética do Agente Público e da Alta Administração Estadual de Minas Gerais, assinale a opção correta. A É vedado ao agente público permitir que interesses particulares prevaleçam sobre o interesse público, bem como participar de qualquer atividade que possa significar conflito de interesse em relação à atividade pública que exerce. B A observância das normas éticas previstas no referido decreto é facultativa, constituindo mera recomendação de boas práticas administrativas. C A atuação das comissões de ética limita-se à aplicação de sanções disciplinares, sendo-lhes vedada a função orientadora ou preventiva. D O referido código de conduta ética aplica-se exclusivamente aos ocupantes de cargos de direção superior, não alcançando servidores efetivos nem empregados públicos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Decreto estadual nº 46.644/2014) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,27,$q$Legislação Institucional da PCMG$q$,$q$Considerando o disposto na Lei estadual n.º 15.301/2004, que instituiu as carreiras do Grupo de Atividades de Defesa Social do Poder Executivo, assinale a opção correta. A O cargo de técnico assistente da polícia civil integra uma das carreiras instituídas por essa lei, e suas atividades envolvem execução de tarefas de apoio técnico, administrativo e logístico compatíveis com o nível intermediário de escolaridade. B A cessão de servidor ocupante de cargo das carreiras instituídas por essa lei para órgão ou entidade sem carreira correspondente é totalmente vedada, sem hipótese de exceção. C As carreiras instituídas pela Lei n.º 15.301/2004 destinam-se exclusivamente à PCMG, não abrangendo outras instituições do Sistema de Defesa Social. D A mudança de lotação e a transferência de servidores entre órgãos e entidades do Poder Executivo estadual poderão ocorrer independentemente de vaga existente no órgão ou entidade de destino, desde que haja interesse público e anuência do servidor interessado.$q$,$q$Considerando o disposto na Lei estadual n.º 15.301/2004, que instituiu as carreiras do Grupo de Atividades de Defesa Social do Poder Executivo, assinale a opção correta. A O cargo de técnico assistente da polícia civil integra uma das carreiras instituídas por essa lei, e suas atividades envolvem execução de tarefas de apoio técnico, administrativo e logístico compatíveis com o nível intermediário de escolaridade. B A cessão de servidor ocupante de cargo das carreiras instituídas por essa lei para órgão ou entidade sem carreira correspondente é totalmente vedada, sem hipótese de exceção. C As carreiras instituídas pela Lei n.º 15.301/2004 destinam-se exclusivamente à PCMG, não abrangendo outras instituições do Sistema de Defesa Social. D A mudança de lotação e a transferência de servidores entre órgãos e entidades do Poder Executivo estadual poderão ocorrer independentemente de vaga existente no órgão ou entidade de destino, desde que haja interesse público e anuência do servidor interessado.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Lei estadual nº 15.301/2004) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,28,$q$Legislação Institucional da PCMG$q$,$q$Acerca do processo administrativo disciplinar, assinale a opção correta, conforme disposto na Lei estadual n.º 869/1952. A O processo administrativo disciplinar deve ser conduzido por comissão composta por três membros, podendo integrá-las inclusive ocupantes de cargos comissionados. B O inquérito administrativo, quando instaurado como fase prévia do processo administrativo disciplinar, possui natureza decisória e pode, por si só, ensejar a aplicação de qualquer penalidade, inclusive a demissão do servidor. C A revisão do processo administrativo pode ser requerida a qualquer tempo diante de fatos que justifiquem a inocência do servidor, podendo ser solicitada mesmo após seu falecimento ou desaparecimento. D No âmbito do processo administrativo, a fase de inquérito administrativo é sempre facultativa.$q$,$q$Acerca do processo administrativo disciplinar, assinale a opção correta, conforme disposto na Lei estadual n.º 869/1952. A O processo administrativo disciplinar deve ser conduzido por comissão composta por três membros, podendo integrá-las inclusive ocupantes de cargos comissionados. B O inquérito administrativo, quando instaurado como fase prévia do processo administrativo disciplinar, possui natureza decisória e pode, por si só, ensejar a aplicação de qualquer penalidade, inclusive a demissão do servidor. C A revisão do processo administrativo pode ser requerida a qualquer tempo diante de fatos que justifiquem a inocência do servidor, podendo ser solicitada mesmo após seu falecimento ou desaparecimento. D No âmbito do processo administrativo, a fase de inquérito administrativo é sempre facultativa.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Lei estadual nº 869/1952) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,29,$q$Legislação Institucional da PCMG$q$,$q$De acordo com o Estatuto dos Funcionários Públicos Civis do Estado de Minas Gerais (Lei estadual n.º 869/1952), assinale a opção correta a respeito do estágio probatório. A O servidor em estágio probatório adquire automaticamente estabilidade no cargo com o decurso do prazo legal do estágio, dispensando-se a necessidade de avaliação de desempenho pelo órgão de pessoal. B Caso o parecer do órgão de pessoal seja contrário à confirmação do servidor no cargo, será assegurada vista ao estagiário pelo prazo de cinco dias antes da decisão administrativa competente. C O despacho favorável do governador do estado à permanência do funcionário no cargo deve ser submetido ao órgão de pessoal para confirmação e produção de efeitos. D Durante o estágio probatório, serão avaliados exclusivamente os requisitos de eficiência e disciplina, sendo a assiduidade considerada apenas após a aquisição da estabilidade.$q$,$q$De acordo com o Estatuto dos Funcionários Públicos Civis do Estado de Minas Gerais (Lei estadual n.º 869/1952), assinale a opção correta a respeito do estágio probatório. A O servidor em estágio probatório adquire automaticamente estabilidade no cargo com o decurso do prazo legal do estágio, dispensando-se a necessidade de avaliação de desempenho pelo órgão de pessoal. B Caso o parecer do órgão de pessoal seja contrário à confirmação do servidor no cargo, será assegurada vista ao estagiário pelo prazo de cinco dias antes da decisão administrativa competente. C O despacho favorável do governador do estado à permanência do funcionário no cargo deve ser submetido ao órgão de pessoal para confirmação e produção de efeitos. D Durante o estágio probatório, serão avaliados exclusivamente os requisitos de eficiência e disciplina, sendo a assiduidade considerada apenas após a aquisição da estabilidade.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Lei estadual nº 869/1952) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,30,$q$Legislação Institucional da PCMG$q$,$q$De acordo com a Lei estadual n.º 15.301/2004, que institui as carreiras do Grupo de Atividades de Defesa Social do Poder Executivo, o ingresso nas referidas carreiras ocorre por meio de A concurso público de provas ou de provas e títulos, conforme previsto em lei. B nomeação em cargo em comissão, após processo seletivo simplificado. C promoção interna, mediante avaliação de desempenho e tempo de serviço. D contratação temporária, para atender a necessidade excepcional de interesse público.$q$,$q$De acordo com a Lei estadual n.º 15.301/2004, que institui as carreiras do Grupo de Atividades de Defesa Social do Poder Executivo, o ingresso nas referidas carreiras ocorre por meio de A concurso público de provas ou de provas e títulos, conforme previsto em lei. B nomeação em cargo em comissão, após processo seletivo simplificado. C promoção interna, mediante avaliação de desempenho e tempo de serviço. D contratação temporária, para atender a necessidade excepcional de interesse público.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Legislação, fileId 18oY3og5Gj1GfjLnBRmkwx1C0tmLuwg8_); gabarito conferido em Gabarito definitivo Eixo Legislação (fileId 10z3Cj3oGsehCmjvKLUJ5IemwVkODR1Ux). Base legal (Lei estadual nº 15.301/2004) ainda não conferida individualmente na fonte oficial de MG - aguardando revisão item a item antes de content_status=active.$q$),
(2025,31,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em uma investigação de homicídio, foi designado um técnico auxiliar para apoiar os peritos na cena do crime, cometido em um apartamento fechado, onde o corpo foi encontrado em decomposição inicial. Na chegada ao local, a prioridade imediata é garantir a preservação das evidências biológicas no corpo. Nessa situação hipotética, deve-se inicialmente A cobrir o corpo diretamente com barreiras plásticas, para evitar contaminação externa. B documentar fotograficamente o corpo na posição em que foi encontrado, antes de realizar qualquer manipulação. C aplicar desinfetante no ambiente, para reduzir odores e riscos biológicos. D realizar a limpeza superficial do corpo, para facilitar o exame visual.$q$,$q$Em uma investigação de homicídio, foi designado um técnico auxiliar para apoiar os peritos na cena do crime, cometido em um apartamento fechado, onde o corpo foi encontrado em decomposição inicial. Na chegada ao local, a prioridade imediata é garantir a preservação das evidências biológicas no corpo. Nessa situação hipotética, deve-se inicialmente A cobrir o corpo diretamente com barreiras plásticas, para evitar contaminação externa. B documentar fotograficamente o corpo na posição em que foi encontrado, antes de realizar qualquer manipulação. C aplicar desinfetante no ambiente, para reduzir odores e riscos biológicos. D realizar a limpeza superficial do corpo, para facilitar o exame visual.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,32,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em uma necropsia no IML, um técnico auxiliar atua na preparação de um corpo recuperado de uma enchente, com sinais de afogamento e possível presença de detritos orgânicos. Durante o procedimento, surge a necessidade de coletar amostras de tecidos para análise toxicológica. Nessa situação hipotética, o passo operacional correto para auxiliar nessa coleta é A armazenar as amostras em temperatura ambiente até o final da necropsia, para reduzir o tempo de realização da perícia. B preparar kits estéreis com lâminas e frascos herméticos, bem como garantir a identificação imediata das amostras. C realizar a coleta após a lavagem completa do corpo, para evitar contaminação das amostras. D coletar as amostras diretamente, com pinças comuns, e armazená-las em recipientes plásticos devidamente identificados.$q$,$q$Em uma necropsia no IML, um técnico auxiliar atua na preparação de um corpo recuperado de uma enchente, com sinais de afogamento e possível presença de detritos orgânicos. Durante o procedimento, surge a necessidade de coletar amostras de tecidos para análise toxicológica. Nessa situação hipotética, o passo operacional correto para auxiliar nessa coleta é A armazenar as amostras em temperatura ambiente até o final da necropsia, para reduzir o tempo de realização da perícia. B preparar kits estéreis com lâminas e frascos herméticos, bem como garantir a identificação imediata das amostras. C realizar a coleta após a lavagem completa do corpo, para evitar contaminação das amostras. D coletar as amostras diretamente, com pinças comuns, e armazená-las em recipientes plásticos devidamente identificados.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,33,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em apoio a uma perícia médico-legal de acidente de trânsito fatal, o técnico auxiliar participa da remoção do corpo de dentro de um veículo danificado, para transporte ao instituto médico-legal (IML). O corpo exibe lesões externas visíveis e possível contaminação por fluidos automotivos (como óleo ou gasolina). Nessa situação hipotética, o procedimento operacional padrão para garantir o manuseio seguro do corpo pelo técnico auxiliar e a preservação integral das evidências no corpo, conforme protocolos de biossegurança e perícia forense, consiste em A retirar do veículo o corpo e posicioná-lo ao ar livre, permitindo secagem natural dos tecidos e resíduos, antes de prosseguir com o transporte. B utilizar luvas de látex nitrílicas padrão e extrair o corpo diretamente para uma maca convencional. C empregar prancha rígida de imobilização espinhal e, antes de qualquer contato direto com o corpo, paramentar-se com conjunto completo de equipamentos de proteção individual (EPI), incluídos macacão impermeável, máscara respiratória e óculos de proteção. D realizar lavagem imediata do corpo com água e sabão neutro no local do acidente, para eliminar detritos e fluidos antes da remoção do corpo.$q$,$q$Em apoio a uma perícia médico-legal de acidente de trânsito fatal, o técnico auxiliar participa da remoção do corpo de dentro de um veículo danificado, para transporte ao instituto médico-legal (IML). O corpo exibe lesões externas visíveis e possível contaminação por fluidos automotivos (como óleo ou gasolina). Nessa situação hipotética, o procedimento operacional padrão para garantir o manuseio seguro do corpo pelo técnico auxiliar e a preservação integral das evidências no corpo, conforme protocolos de biossegurança e perícia forense, consiste em A retirar do veículo o corpo e posicioná-lo ao ar livre, permitindo secagem natural dos tecidos e resíduos, antes de prosseguir com o transporte. B utilizar luvas de látex nitrílicas padrão e extrair o corpo diretamente para uma maca convencional. C empregar prancha rígida de imobilização espinhal e, antes de qualquer contato direto com o corpo, paramentar-se com conjunto completo de equipamentos de proteção individual (EPI), incluídos macacão impermeável, máscara respiratória e óculos de proteção. D realizar lavagem imediata do corpo com água e sabão neutro no local do acidente, para eliminar detritos e fluidos antes da remoção do corpo.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,34,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Um técnico auxiliar, em uma cena de afogamento em rio urbano, participa da recuperação e movimentação de um corpo já em fase enfisematosa após imersão prolongada, havendo risco de liberação de gases e fluidos. O transporte para o IML exige técnicas que minimizem riscos biológicos e ergonômicos à equipe e que, simultaneamente, preservem o corpo até a realização da perícia. Nessa situação hipotética, o procedimento mais adequado de movimentação do corpo inclui A colocar o corpo em contêiner plástico, selado imediatamente após a recuperação aquática. B envolvê-lo em lonas impermeáveis, para conter fluidos durante o carregamento manual. C realizar sua movimentação em dupla, segurando-o pelas axilas e pelos pés, para melhor distribuição de peso. D utilizar macas com barreiras laterais, para drenagem controlada, estando a equipe paramentada com os EPI obrigatórios.$q$,$q$Um técnico auxiliar, em uma cena de afogamento em rio urbano, participa da recuperação e movimentação de um corpo já em fase enfisematosa após imersão prolongada, havendo risco de liberação de gases e fluidos. O transporte para o IML exige técnicas que minimizem riscos biológicos e ergonômicos à equipe e que, simultaneamente, preservem o corpo até a realização da perícia. Nessa situação hipotética, o procedimento mais adequado de movimentação do corpo inclui A colocar o corpo em contêiner plástico, selado imediatamente após a recuperação aquática. B envolvê-lo em lonas impermeáveis, para conter fluidos durante o carregamento manual. C realizar sua movimentação em dupla, segurando-o pelas axilas e pelos pés, para melhor distribuição de peso. D utilizar macas com barreiras laterais, para drenagem controlada, estando a equipe paramentada com os EPI obrigatórios.$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,35,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Durante apoio a uma perícia após morte suspeita em hospital, o técnico auxiliar coordena a movimentação de um corpo obeso com dispositivos médicos inseridos, para transferência ao IML via elevador. A técnica deve garantir estabilidade e preservação de tubos e cateteres como evidências. Nesse caso hipotético, a abordagem operacional mais adequada para essa movimentação consiste em A usar macas hidráulicas com capacidade reforçada, dispondo-se de uma equipe de, pelo menos, quatro auxiliares para movimentação do corpo com os dispositivos médicos preservados. B realizar documentação fotográfica e remover os dispositivos no local, para reduzir o peso e facilitar o carregamento. C posicionar o corpo de lado no elevador, para otimizar espaço e equilíbrio. D empregar cintas de elevação sob os braços do corpo, para distribuição de peso durante a descida.$q$,$q$Durante apoio a uma perícia após morte suspeita em hospital, o técnico auxiliar coordena a movimentação de um corpo obeso com dispositivos médicos inseridos, para transferência ao IML via elevador. A técnica deve garantir estabilidade e preservação de tubos e cateteres como evidências. Nesse caso hipotético, a abordagem operacional mais adequada para essa movimentação consiste em A usar macas hidráulicas com capacidade reforçada, dispondo-se de uma equipe de, pelo menos, quatro auxiliares para movimentação do corpo com os dispositivos médicos preservados. B realizar documentação fotográfica e remover os dispositivos no local, para reduzir o peso e facilitar o carregamento. C posicionar o corpo de lado no elevador, para otimizar espaço e equilíbrio. D empregar cintas de elevação sob os braços do corpo, para distribuição de peso durante a descida.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,36,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em uma operação noturna de perícia criminal em floresta, um técnico auxiliar atua na movimentação de um corpo com suspeita de sepultamento clandestino. O corpo apresenta rigidez avançada e solo aderido. O terreno irregular exige técnicas que preservem evidências de sepultura para análise forense. Considerando-se o método de transporte mais apropriado para essa condição, é correto afirmar que, no caso, é necessário A envolver o corpo em plásticos, para protegê-lo contra arranhaduras post mortem durante o deslocamento. B usar cordas para arrastar o corpo ao longo do caminho até o veículo de remoção. C mobilizar o corpo verticalmente com alavancas, para superar obstáculos no terreno. D empregar suportes portáteis com rodas off-road (apropriadas a terrenos irregulares) e fixação para manter a orientação do corpo.$q$,$q$Em uma operação noturna de perícia criminal em floresta, um técnico auxiliar atua na movimentação de um corpo com suspeita de sepultamento clandestino. O corpo apresenta rigidez avançada e solo aderido. O terreno irregular exige técnicas que preservem evidências de sepultura para análise forense. Considerando-se o método de transporte mais apropriado para essa condição, é correto afirmar que, no caso, é necessário A envolver o corpo em plásticos, para protegê-lo contra arranhaduras post mortem durante o deslocamento. B usar cordas para arrastar o corpo ao longo do caminho até o veículo de remoção. C mobilizar o corpo verticalmente com alavancas, para superar obstáculos no terreno. D empregar suportes portáteis com rodas off-road (apropriadas a terrenos irregulares) e fixação para manter a orientação do corpo.$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,37,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Durante uma perícia em contexto de pandemia, o técnico auxiliar atua no armazenamento de um corpo com suspeita de infecção transmissível, recuperado de isolamento domiciliar, com fluidos corporais presentes. O armazenamento deve priorizar a biossegurança e a preservação para autópsia etiológica. Nesse caso hipotético, o protocolo de armazenamento mais seguro e adequado para essa operação técnica consiste em A armazenar o corpo em duplo envoltório plástico e introduzi-lo em câmara a 4 °C, para contenção da propagação viral. B colocar o corpo em sacos biohazard (indicativos de risco biológico) à temperatura ambiente, para processamento rápido. C manter o corpo em freezer industrial a −10 °C, para inativação imediata de patógenos. D utilizar unidade de refrigeração isolada a 2 °C, com ventilação filtrada, sendo obrigatório o uso dos EPI pela equipe.$q$,$q$Durante uma perícia em contexto de pandemia, o técnico auxiliar atua no armazenamento de um corpo com suspeita de infecção transmissível, recuperado de isolamento domiciliar, com fluidos corporais presentes. O armazenamento deve priorizar a biossegurança e a preservação para autópsia etiológica. Nesse caso hipotético, o protocolo de armazenamento mais seguro e adequado para essa operação técnica consiste em A armazenar o corpo em duplo envoltório plástico e introduzi-lo em câmara a 4 °C, para contenção da propagação viral. B colocar o corpo em sacos biohazard (indicativos de risco biológico) à temperatura ambiente, para processamento rápido. C manter o corpo em freezer industrial a −10 °C, para inativação imediata de patógenos. D utilizar unidade de refrigeração isolada a 2 °C, com ventilação filtrada, sendo obrigatório o uso dos EPI pela equipe.$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,38,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em uma operação de perícia criminal após um desastre natural com múltiplas vítimas, o técnico auxiliar atua no armazenamento temporário de um corpo recuperado de escombros, com sinais iniciais de decomposição e possível contaminação por detritos orgânicos. O IML está sobrecarregado, logo é necessária a preservação das evidências biológicas até o transporte. Nessa situação hipotética, o método de armazenamento mais apropriado para essa condição operacional é A envolver o corpo em lonas absorventes e posicioná-lo em área sombreada externa. B utilizar câmara refrigerada a até 4 °C, com identificação e monitoramento de umidade, para retardar putrefação. C armazenar o corpo em contêineres de madeira vazados, com exposição ao ar ambiente, para permitir ventilação natural. D colocar o corpo em sacos plásticos, selados em temperatura ambiente, para contenção de odores e preservação das amostras.$q$,$q$Em uma operação de perícia criminal após um desastre natural com múltiplas vítimas, o técnico auxiliar atua no armazenamento temporário de um corpo recuperado de escombros, com sinais iniciais de decomposição e possível contaminação por detritos orgânicos. O IML está sobrecarregado, logo é necessária a preservação das evidências biológicas até o transporte. Nessa situação hipotética, o método de armazenamento mais apropriado para essa condição operacional é A envolver o corpo em lonas absorventes e posicioná-lo em área sombreada externa. B utilizar câmara refrigerada a até 4 °C, com identificação e monitoramento de umidade, para retardar putrefação. C armazenar o corpo em contêineres de madeira vazados, com exposição ao ar ambiente, para permitir ventilação natural. D colocar o corpo em sacos plásticos, selados em temperatura ambiente, para contenção de odores e preservação das amostras.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,39,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Durante pico de casos de homicídio em determinada localidade, um técnico auxiliar no IML organiza o uso de câmaras frias para múltiplos corpos em diferentes estágios de decomposição, incluindo um com rigidez avançada. Deve-se otimizar o espaço da câmara e preservar evidências para necropsias sequenciais. Nessa situação hipotética, a câmara fria deve ser configurada A à temperatura de 5 °C, com ventiladores internos, para uniformidade térmica geral. B à temperatura de 0 °C, alocando-se os corpos em sacos plásticos e em empilhamento direto, para maximizar a capacidade. C a uma temperatura entre 2 °C até 4 °C, com divisórias isoladas e sensores de temperatura por prateleira. D à temperatura de 10 °C, com prateleiras abertas, para circulação de ar entre corpos.$q$,$q$Durante pico de casos de homicídio em determinada localidade, um técnico auxiliar no IML organiza o uso de câmaras frias para múltiplos corpos em diferentes estágios de decomposição, incluindo um com rigidez avançada. Deve-se otimizar o espaço da câmara e preservar evidências para necropsias sequenciais. Nessa situação hipotética, a câmara fria deve ser configurada A à temperatura de 5 °C, com ventiladores internos, para uniformidade térmica geral. B à temperatura de 0 °C, alocando-se os corpos em sacos plásticos e em empilhamento direto, para maximizar a capacidade. C a uma temperatura entre 2 °C até 4 °C, com divisórias isoladas e sensores de temperatura por prateleira. D à temperatura de 10 °C, com prateleiras abertas, para circulação de ar entre corpos.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,40,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em uma operação de perícia criminal em escadaria urbana após queda fatal, o técnico auxiliar atua na colocação de um corpo com lesões espinhais visíveis em uma maca, para descida controlada até o veículo de remoção. O equipamento deve suportar o peso e preservar o alinhamento postural para análise de fraturas no IML. Considerando a situação hipotética apresentada, assinale a opção que descreve o tipo de maca mais apropriado para essa movimentação operacional. A maca inflável portátil para amortecimento suave durante a descida B maca de lona reforçada com alças manuais para distribuição de esforço da equipe C maca rígida com espuma ortopédica e fixadores laterais para suporte espinhal D maca dobrável de alumínio leve para manobrabilidade em espaços restritos$q$,$q$Em uma operação de perícia criminal em escadaria urbana após queda fatal, o técnico auxiliar atua na colocação de um corpo com lesões espinhais visíveis em uma maca, para descida controlada até o veículo de remoção. O equipamento deve suportar o peso e preservar o alinhamento postural para análise de fraturas no IML. Considerando a situação hipotética apresentada, assinale a opção que descreve o tipo de maca mais apropriado para essa movimentação operacional. A maca inflável portátil para amortecimento suave durante a descida B maca de lona reforçada com alças manuais para distribuição de esforço da equipe C maca rígida com espuma ortopédica e fixadores laterais para suporte espinhal D maca dobrável de alumínio leve para manobrabilidade em espaços restritos$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,41,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Um corpo é admitido no instituto médico legal (IML) em estado avançado de decomposição, o que dificulta a sua identificação visual. O auxiliar de necropsia, sob supervisão, é responsável pela recepção do corpo e pela sua identificação. Nessa situação, a conduta prioritária a ser realizada pelo auxiliar para garantir a correta identificação e o manejo inicial do corpo é A descartar, para evitar contaminação, objetos pessoais que tenham sido transportados junto ao corpo e envolver o cadáver em lona plástica antes de qualquer registro. B iniciar imediatamente a preparação para a necropsia, visando agilizar o processo, visto que a identificação nesse caso levaria muito tempo. C conferir a documentação de entrada (guia de remoção/requisição), verificar e registrar quaisquer marcas ou objetos que possam auxiliar na identificação, e documentar fotograficamente o estado do corpo antes do acondicionamento adequado. D registrar o corpo como “não identificado” e encaminhá-lo diretamente para a câmara fria, aguardando a chegada de familiares para reconhecimento.$q$,$q$Um corpo é admitido no instituto médico legal (IML) em estado avançado de decomposição, o que dificulta a sua identificação visual. O auxiliar de necropsia, sob supervisão, é responsável pela recepção do corpo e pela sua identificação. Nessa situação, a conduta prioritária a ser realizada pelo auxiliar para garantir a correta identificação e o manejo inicial do corpo é A descartar, para evitar contaminação, objetos pessoais que tenham sido transportados junto ao corpo e envolver o cadáver em lona plástica antes de qualquer registro. B iniciar imediatamente a preparação para a necropsia, visando agilizar o processo, visto que a identificação nesse caso levaria muito tempo. C conferir a documentação de entrada (guia de remoção/requisição), verificar e registrar quaisquer marcas ou objetos que possam auxiliar na identificação, e documentar fotograficamente o estado do corpo antes do acondicionamento adequado. D registrar o corpo como “não identificado” e encaminhá-lo diretamente para a câmara fria, aguardando a chegada de familiares para reconhecimento.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,42,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Antes do início de uma necropsia, o item indispensável para garantir a assepsia e a segurança da equipe no ambiente de trabalho é a A lanterna forense ultravioleta (UV). B solução desinfetante de amplo espectro para superfícies. C câmera fotográfica com tripé. D balança para órgãos.$q$,$q$Antes do início de uma necropsia, o item indispensável para garantir a assepsia e a segurança da equipe no ambiente de trabalho é a A lanterna forense ultravioleta (UV). B solução desinfetante de amplo espectro para superfícies. C câmera fotográfica com tripé. D balança para órgãos.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,43,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Suponha que, durante um exame necroscópico, o médico legista solicite ao auxiliar de necropsia que colete uma amostra de sangue para exames toxicológicos. Nesse caso, o procedimento mais adequado para a coleta dessa amostra pelo auxiliar de necropsia, com vistas a preservar sua integridade e a cadeia de custódia, é A solicitar ao médico legista que ele mesmo realize a coleta, pois esta é uma tarefa exclusivamente médica. B utilizar seringa e agulha estéreis para coletar o sangue diretamente de um vaso calibroso, transferindo-o para tubo adequado, identificando-o imediatamente. C coletar o sangue com uma pipeta descartável e depositá-lo em um saco plástico hermético. D coletar o sangue em um frasco genérico, rotulando-o apenas após a conclusão do exame.$q$,$q$Suponha que, durante um exame necroscópico, o médico legista solicite ao auxiliar de necropsia que colete uma amostra de sangue para exames toxicológicos. Nesse caso, o procedimento mais adequado para a coleta dessa amostra pelo auxiliar de necropsia, com vistas a preservar sua integridade e a cadeia de custódia, é A solicitar ao médico legista que ele mesmo realize a coleta, pois esta é uma tarefa exclusivamente médica. B utilizar seringa e agulha estéreis para coletar o sangue diretamente de um vaso calibroso, transferindo-o para tubo adequado, identificando-o imediatamente. C coletar o sangue com uma pipeta descartável e depositá-lo em um saco plástico hermético. D coletar o sangue em um frasco genérico, rotulando-o apenas após a conclusão do exame.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,44,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$A principal função do uso de solução de formaldeído (formol) a 10% tamponado na preservação de tecidos e órgãos coletados durante a necropsia é A fixar as estruturas celulares, prevenindo a autólise e a putrefação dos tecidos e permitindo exames histopatológicos posteriores. B acelerar o processo de decomposição, para facilitar o posterior descarte dos tecidos. C manter a flexibilidade dos tecidos para futura reconstrução facial. D eliminar completamente todos os microrganismos presentes na amostra.$q$,$q$A principal função do uso de solução de formaldeído (formol) a 10% tamponado na preservação de tecidos e órgãos coletados durante a necropsia é A fixar as estruturas celulares, prevenindo a autólise e a putrefação dos tecidos e permitindo exames histopatológicos posteriores. B acelerar o processo de decomposição, para facilitar o posterior descarte dos tecidos. C manter a flexibilidade dos tecidos para futura reconstrução facial. D eliminar completamente todos os microrganismos presentes na amostra.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,45,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Ao final de um dia de trabalho intenso no setor de necropsia, a equipe se prepara para a limpeza e a organização do ambiente. O auxiliar de necropsia percebe que há, sobre a bancada, instrumentos cirúrgicos metálicos sujos e materiais de consumo descartáveis previamente utilizados. Na situação hipotética precedente, para lidar apropriadamente com esses materiais, visando à segurança e à eficiência da organização pós-trabalho, o auxiliar de necropsia deve A deixar os materiais sobre a bancada para serem limpos e organizados pela equipe do turno seguinte. B separar os instrumentos metálicos para pré-limpeza e encaminhamento à esterilização, e descartar os materiais descartáveis em lixo comum. C descartar os materiais descartáveis em recipiente específico para resíduos biológicos infectantes e encaminhar os instrumentos metálicos para pré-limpeza e desinfecção. D descartar todos os materiais juntos em um único saco de lixo, para agilizar o processo.$q$,$q$Ao final de um dia de trabalho intenso no setor de necropsia, a equipe se prepara para a limpeza e a organização do ambiente. O auxiliar de necropsia percebe que há, sobre a bancada, instrumentos cirúrgicos metálicos sujos e materiais de consumo descartáveis previamente utilizados. Na situação hipotética precedente, para lidar apropriadamente com esses materiais, visando à segurança e à eficiência da organização pós-trabalho, o auxiliar de necropsia deve A deixar os materiais sobre a bancada para serem limpos e organizados pela equipe do turno seguinte. B separar os instrumentos metálicos para pré-limpeza e encaminhamento à esterilização, e descartar os materiais descartáveis em lixo comum. C descartar os materiais descartáveis em recipiente específico para resíduos biológicos infectantes e encaminhar os instrumentos metálicos para pré-limpeza e desinfecção. D descartar todos os materiais juntos em um único saco de lixo, para agilizar o processo.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,46,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Um cadáver em avançado estado de decomposição chega ao IML, sem documentos de identificação. Há suspeita de que a identificação visual e papiloscópica sejam inviáveis. O auxiliar de necropsia é instruído a preparar a sala e os materiais para uma necropsia focada em métodos de identificação indireta. Nessa situação hipotética, a preparação mais adequada que o auxiliar de necropsia deve garantir, antes do início do exame, para otimizar a coleta de materiais para identificação, é A assegurar a disponibilidade de frascos estéreis e tubos adequados para a coleta de fluidos, além de recipientes apropriados para acondicionamento de ossos ou dentes para análise de DNA e odontologia legal. B providenciar uma câmera de alta resolução para documentação fotográfica dos vestígios. C isolar o corpo em um ambiente separado por 24 horas, para aguardar uma possível identificação visual por familiares. D preparar os instrumentos de rotina, aguardando instruções específicas do médico legista durante o exame.$q$,$q$Um cadáver em avançado estado de decomposição chega ao IML, sem documentos de identificação. Há suspeita de que a identificação visual e papiloscópica sejam inviáveis. O auxiliar de necropsia é instruído a preparar a sala e os materiais para uma necropsia focada em métodos de identificação indireta. Nessa situação hipotética, a preparação mais adequada que o auxiliar de necropsia deve garantir, antes do início do exame, para otimizar a coleta de materiais para identificação, é A assegurar a disponibilidade de frascos estéreis e tubos adequados para a coleta de fluidos, além de recipientes apropriados para acondicionamento de ossos ou dentes para análise de DNA e odontologia legal. B providenciar uma câmera de alta resolução para documentação fotográfica dos vestígios. C isolar o corpo em um ambiente separado por 24 horas, para aguardar uma possível identificação visual por familiares. D preparar os instrumentos de rotina, aguardando instruções específicas do médico legista durante o exame.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,47,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Assinale a opção em que é apresentada a classe de desinfetantes geralmente recomendada para a desinfecção de superfícies e equipamentos em sala de necropsia, especialmente em caso de alto risco de contaminação por agentes biológicos resistentes. A esterilizantes químicos a frio (ex.: glutaraldeído em uso contínuo para superfícies) B desinfetantes de nível intermediário a alto (ex.: compostos clorados, fenólicos) C desinfetantes de baixo nível (ex.: sabão neutro) D desinfetantes antissépticos para pele (ex.: clorexidina)$q$,$q$Assinale a opção em que é apresentada a classe de desinfetantes geralmente recomendada para a desinfecção de superfícies e equipamentos em sala de necropsia, especialmente em caso de alto risco de contaminação por agentes biológicos resistentes. A esterilizantes químicos a frio (ex.: glutaraldeído em uso contínuo para superfícies) B desinfetantes de nível intermediário a alto (ex.: compostos clorados, fenólicos) C desinfetantes de baixo nível (ex.: sabão neutro) D desinfetantes antissépticos para pele (ex.: clorexidina)$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,48,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$A principal limitação da refrigeração, em temperaturas entre 0 °C e 4 °C, como método de preservação de cadáveres e tecidos para exames periciais prolongados é o fato de que A a refrigeração promove a proliferação de microrganismos anaeróbios, acelerando a decomposição. B a refrigeração não impede completamente a ocorrência de processos autolíticos e putrefativos, apenas os retarda. C a exposição prolongada ao frio causa endurecimento irreversível dos tecidos, inviabilizando a manipulação. D a refrigeração impede a coleta de amostras para toxicologia após 24 horas.$q$,$q$A principal limitação da refrigeração, em temperaturas entre 0 °C e 4 °C, como método de preservação de cadáveres e tecidos para exames periciais prolongados é o fato de que A a refrigeração promove a proliferação de microrganismos anaeróbios, acelerando a decomposição. B a refrigeração não impede completamente a ocorrência de processos autolíticos e putrefativos, apenas os retarda. C a exposição prolongada ao frio causa endurecimento irreversível dos tecidos, inviabilizando a manipulação. D a refrigeração impede a coleta de amostras para toxicologia após 24 horas.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,49,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Durante a necropsia de um indivíduo falecido por suspeita de envenenamento por cianeto, o auxiliar de necropsia é solicitado a auxiliar o médio legista na coleta de amostras de tecidos para toxicologia e, posteriormente, na descontaminação dos instrumentos e do ambiente. Sabendo que a inalação de cianeto é extremamente perigosa e considerando a natureza volátil e tóxica do cianeto, a sequência de ações prioritárias e mais seguras que o auxiliar de necropsia deve adotar durante a coleta das amostras e, subsequentemente, na limpeza dos materiais e ambiente após o exame é A utilizar equipamentos de proteção individual (EPI) adequados (máscara com filtro, luvas duplas); coletar as amostras em frascos herméticos com vedação segura; e, para a limpeza, utilizar desinfetantes oxidantes (como hipoclorito diluído) em ambiente ventilado, descartando os resíduos quimicamente perigosos em recipiente específico. B apenas utilizar luvas; coletar as amostras rapidamente em sacos plásticos; e, após o exame, submergir todos os instrumentos em álcool 70% por 10 minutos antes de descartar os resíduos em saco branco. C solicitar que o médico legista realize toda a coleta e limpeza, pois a tarefa é de alta periculosidade e não compete ao auxiliar de necropsia. D coletar as amostras em recipientes abertos para rápida evaporação do cianeto; lavar os instrumentos com água quente e sabão; e descartar resíduos no lixo comum.$q$,$q$Durante a necropsia de um indivíduo falecido por suspeita de envenenamento por cianeto, o auxiliar de necropsia é solicitado a auxiliar o médio legista na coleta de amostras de tecidos para toxicologia e, posteriormente, na descontaminação dos instrumentos e do ambiente. Sabendo que a inalação de cianeto é extremamente perigosa e considerando a natureza volátil e tóxica do cianeto, a sequência de ações prioritárias e mais seguras que o auxiliar de necropsia deve adotar durante a coleta das amostras e, subsequentemente, na limpeza dos materiais e ambiente após o exame é A utilizar equipamentos de proteção individual (EPI) adequados (máscara com filtro, luvas duplas); coletar as amostras em frascos herméticos com vedação segura; e, para a limpeza, utilizar desinfetantes oxidantes (como hipoclorito diluído) em ambiente ventilado, descartando os resíduos quimicamente perigosos em recipiente específico. B apenas utilizar luvas; coletar as amostras rapidamente em sacos plásticos; e, após o exame, submergir todos os instrumentos em álcool 70% por 10 minutos antes de descartar os resíduos em saco branco. C solicitar que o médico legista realize toda a coleta e limpeza, pois a tarefa é de alta periculosidade e não compete ao auxiliar de necropsia. D coletar as amostras em recipientes abertos para rápida evaporação do cianeto; lavar os instrumentos com água quente e sabão; e descartar resíduos no lixo comum.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,50,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$De acordo com as normas de biossegurança e gerenciamento de resíduos de serviços de saúde (RSS), assinale a opção que apresenta a correta classificação e o destino final adequado de uma amostra histopatológica fixada em formol a 10% e embalada em recipiente selado, após a análise pericial e a conclusão de que a amostra não será mais utilizada. A A amostra deve ser classificada como resíduo do grupo D (resíduo comum), podendo ser descartada como lixo doméstico após a remoção do formaldeído. B A amostra deve ser classificada como resíduo do grupo B (químico), exigindo tratamento específico para desativação do formaldeído antes do descarte em aterro sanitário licenciado. C A amostra deve ser classificada como resíduo do grupo C (radioativo), necessitando de segregação e descarte em local específico para materiais nucleares. D A amostra deve ser classificada como resíduo do grupo A (infectante), devendo ser incinerada ou submetida a tratamento por autoclave.$q$,$q$De acordo com as normas de biossegurança e gerenciamento de resíduos de serviços de saúde (RSS), assinale a opção que apresenta a correta classificação e o destino final adequado de uma amostra histopatológica fixada em formol a 10% e embalada em recipiente selado, após a análise pericial e a conclusão de que a amostra não será mais utilizada. A A amostra deve ser classificada como resíduo do grupo D (resíduo comum), podendo ser descartada como lixo doméstico após a remoção do formaldeído. B A amostra deve ser classificada como resíduo do grupo B (químico), exigindo tratamento específico para desativação do formaldeído antes do descarte em aterro sanitário licenciado. C A amostra deve ser classificada como resíduo do grupo C (radioativo), necessitando de segregação e descarte em local específico para materiais nucleares. D A amostra deve ser classificada como resíduo do grupo A (infectante), devendo ser incinerada ou submetida a tratamento por autoclave.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,51,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$A biossegurança é um campo interdisciplinar que orienta práticas em ambientes de saúde, laboratoriais e forenses. Acerca de seus conceitos básicos, assinale a opção correta. A A biossegurança busca eliminar totalmente os riscos ocupacionais, adotando preferencialmente medidas baseadas no uso de EPI. B O princípio da precaução determina que medidas preventivas só sejam adotadas após comprovação científica do risco. C O cumprimento das normas de biossegurança é responsabilidade individual exclusiva do trabalhador diretamente exposto ao risco. D A avaliação de risco em biossegurança deve considerar agente, atividade, vias de exposição e condições do ambiente de trabalho.$q$,$q$A biossegurança é um campo interdisciplinar que orienta práticas em ambientes de saúde, laboratoriais e forenses. Acerca de seus conceitos básicos, assinale a opção correta. A A biossegurança busca eliminar totalmente os riscos ocupacionais, adotando preferencialmente medidas baseadas no uso de EPI. B O princípio da precaução determina que medidas preventivas só sejam adotadas após comprovação científica do risco. C O cumprimento das normas de biossegurança é responsabilidade individual exclusiva do trabalhador diretamente exposto ao risco. D A avaliação de risco em biossegurança deve considerar agente, atividade, vias de exposição e condições do ambiente de trabalho.$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,52,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Quanto aos processos de controle de riscos biológicos, assinale a opção correta. A A esterilização reduz a carga microbiana a níveis seguros, sem eliminar totalmente os microrganismos. B A desinfestação está relacionada ao controle de insetos e roedores, e não à eliminação direta de microrganismos. C A descontaminação e a esterilização são processos conceitualmente equivalentes. D A desinfecção elimina todas as formas de vida microbiana, inclusive esporos bacterianos.$q$,$q$Quanto aos processos de controle de riscos biológicos, assinale a opção correta. A A esterilização reduz a carga microbiana a níveis seguros, sem eliminar totalmente os microrganismos. B A desinfestação está relacionada ao controle de insetos e roedores, e não à eliminação direta de microrganismos. C A descontaminação e a esterilização são processos conceitualmente equivalentes. D A desinfecção elimina todas as formas de vida microbiana, inclusive esporos bacterianos.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,53,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$No ambiente forense, diferentes riscos ocupacionais podem coexistir durante necropsias, exumações e análises laboratoriais. Assinale a opção correta a respeito desses riscos. A Os riscos físicos, no ambiente forense, resumem-se à exposição ao frio em câmaras frigoríficas para armazenamento de cadáveres. B O formol, amplamente utilizado em atividades forenses, representa risco químico com potencial de efeitos agudos e crônicos. C Materiais perfurocortantes caracterizam risco físico, segundo a classificação adotada no Brasil. D Riscos biológicos estão restritos a cadáveres recentes e não ocorrem na manipulação de remanescentes ósseos, sobretudo quando secos.$q$,$q$No ambiente forense, diferentes riscos ocupacionais podem coexistir durante necropsias, exumações e análises laboratoriais. Assinale a opção correta a respeito desses riscos. A Os riscos físicos, no ambiente forense, resumem-se à exposição ao frio em câmaras frigoríficas para armazenamento de cadáveres. B O formol, amplamente utilizado em atividades forenses, representa risco químico com potencial de efeitos agudos e crônicos. C Materiais perfurocortantes caracterizam risco físico, segundo a classificação adotada no Brasil. D Riscos biológicos estão restritos a cadáveres recentes e não ocorrem na manipulação de remanescentes ósseos, sobretudo quando secos.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,54,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Considerando caso de acidente ocupacional com material biológico, assinale a opção correta. A A avaliação do risco deve considerar o tipo de material, a via de exposição e a situação sorológica, quando conhecida. B Devem-se aplicar soluções químicas antissépticas na área atingida, como álcool 70%, para reduzir o risco de infecção. C A notificação do acidente somente é obrigatória se houver confirmação de infecção. D O acompanhamento clínico será dispensável se comprovado que o trabalhador utilizava EPI no momento do acidente.$q$,$q$Considerando caso de acidente ocupacional com material biológico, assinale a opção correta. A A avaliação do risco deve considerar o tipo de material, a via de exposição e a situação sorológica, quando conhecida. B Devem-se aplicar soluções químicas antissépticas na área atingida, como álcool 70%, para reduzir o risco de infecção. C A notificação do acidente somente é obrigatória se houver confirmação de infecção. D O acompanhamento clínico será dispensável se comprovado que o trabalhador utilizava EPI no momento do acidente.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,55,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Em relação ao manuseio e ao descarte de materiais cortantes e perfurocortantes, assinale a opção correta. A O risco associado a perfurocortantes restringe-se a lesões físicas. B O reencape manual de agulhas é permitido, devendo ser realizado conforme técnica adequada e com uso de EPI. C Os coletores de perfurocortantes podem ser reutilizados após desinfecção de alto nível. D O descarte deve ocorrer imediatamente após o uso, em recipientes rígidos e resistentes à perfuração.$q$,$q$Em relação ao manuseio e ao descarte de materiais cortantes e perfurocortantes, assinale a opção correta. A O risco associado a perfurocortantes restringe-se a lesões físicas. B O reencape manual de agulhas é permitido, devendo ser realizado conforme técnica adequada e com uso de EPI. C Os coletores de perfurocortantes podem ser reutilizados após desinfecção de alto nível. D O descarte deve ocorrer imediatamente após o uso, em recipientes rígidos e resistentes à perfuração.$q$,'D',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,56,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$A respeito do gerenciamento e do descarte de resíduos em atividades forenses, assinale a opção correta. A O acondicionamento adequado desses resíduos, conforme as normas vigentes, previne vazamentos, acidentes e contaminações. B Por questões de segurança ambiental, todo resíduo infectante deve ser tratado obrigatoriamente no local de geração, não podendo ocorrer em unidades externas. C O gerenciamento inadequado desses resíduos impacta apenas a etapa de disposição final, sem prejuízo das demais. D A segregação dos resíduos pode ocorrer em local distinto daquele onde eles são gerados, sem violação das normas de segurança.$q$,$q$A respeito do gerenciamento e do descarte de resíduos em atividades forenses, assinale a opção correta. A O acondicionamento adequado desses resíduos, conforme as normas vigentes, previne vazamentos, acidentes e contaminações. B Por questões de segurança ambiental, todo resíduo infectante deve ser tratado obrigatoriamente no local de geração, não podendo ocorrer em unidades externas. C O gerenciamento inadequado desses resíduos impacta apenas a etapa de disposição final, sem prejuízo das demais. D A segregação dos resíduos pode ocorrer em local distinto daquele onde eles são gerados, sem violação das normas de segurança.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,57,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$No que se refere à esfera ética e normativa das atividades de necropsia, assinale a opção correta. A A divulgação de imagens necroscópicas é permitida desde que para fins científicos, bastando informar os motivos aos familiares da pessoa necropsiada, ressaltando-se a razoabilidade dos fins, o meio acadêmico de divulgação e a data de sua publicação. B A dignidade do cadáver deve ser respeitada durante todo o procedimento necroscópico. C O consentimento de familiar da pessoa cujo corpo será submetido à necropsia é dispensável em casos específicos, como, por exemplo, quando há interesse acadêmico. D A necropsia médico-legal depende sempre de autorização de familiar da pessoa cujo corpo será submetido à necropsia.$q$,$q$No que se refere à esfera ética e normativa das atividades de necropsia, assinale a opção correta. A A divulgação de imagens necroscópicas é permitida desde que para fins científicos, bastando informar os motivos aos familiares da pessoa necropsiada, ressaltando-se a razoabilidade dos fins, o meio acadêmico de divulgação e a data de sua publicação. B A dignidade do cadáver deve ser respeitada durante todo o procedimento necroscópico. C O consentimento de familiar da pessoa cujo corpo será submetido à necropsia é dispensável em casos específicos, como, por exemplo, quando há interesse acadêmico. D A necropsia médico-legal depende sempre de autorização de familiar da pessoa cujo corpo será submetido à necropsia.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,58,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Considerando o gerenciamento de riscos associados a materiais perfurocortantes, assinale a opção correta. A O risco ocupacional encerra-se após o descarte do material em coletor apropriado, o que representa o fim do ciclo de biossegurança ambiental. B O excesso de preenchimento do coletor de perfurocortantes, mesmo quando o descarte é realizado de forma tecnicamente correta, compromete a eficácia da medida de biossegurança. C A exposição biológica decorrente do manuseio de materiais perfurocortantes é considerada risco secundário. D A habilitação em nível de pós-graduação na área da saúde ou biossegurança, desde que devidamente comprovada, dispensa a necessidade de treinamento e protocolos institucionais voltados à segurança laboratorial e ao gerenciamento de riscos associados a materiais perfurocortantes.$q$,$q$Considerando o gerenciamento de riscos associados a materiais perfurocortantes, assinale a opção correta. A O risco ocupacional encerra-se após o descarte do material em coletor apropriado, o que representa o fim do ciclo de biossegurança ambiental. B O excesso de preenchimento do coletor de perfurocortantes, mesmo quando o descarte é realizado de forma tecnicamente correta, compromete a eficácia da medida de biossegurança. C A exposição biológica decorrente do manuseio de materiais perfurocortantes é considerada risco secundário. D A habilitação em nível de pós-graduação na área da saúde ou biossegurança, desde que devidamente comprovada, dispensa a necessidade de treinamento e protocolos institucionais voltados à segurança laboratorial e ao gerenciamento de riscos associados a materiais perfurocortantes.$q$,'B',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,59,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$No contexto das atividades forenses, a biossegurança orienta práticas que objetivam proteger o trabalhador, o ambiente e a coletividade. Em relação à biossegurança, julgue os seguintes itens. I A biossegurança aplica-se não apenas a ambientes laboratoriais, mas também a atividades externas, como locais de crime e exumações. II A biossegurança envolve medidas técnicas, administrativas e comportamentais, devendo ser incorporada de forma sistemática às rotinas de trabalho. III O uso de EPI é suficiente para garantir a biossegurança, independentemente das condições do ambiente e da organização do trabalho. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos.$q$,$q$No contexto das atividades forenses, a biossegurança orienta práticas que objetivam proteger o trabalhador, o ambiente e a coletividade. Em relação à biossegurança, julgue os seguintes itens. I A biossegurança aplica-se não apenas a ambientes laboratoriais, mas também a atividades externas, como locais de crime e exumações. II A biossegurança envolve medidas técnicas, administrativas e comportamentais, devendo ser incorporada de forma sistemática às rotinas de trabalho. III O uso de EPI é suficiente para garantir a biossegurança, independentemente das condições do ambiente e da organização do trabalho. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens II e III estão certos.$q$,'C',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$),
(2025,60,$q$Conhecimentos Específicos - Auxiliar de Perícia$q$,$q$Acerca dos limites éticos e legais da necropsia, assinale a opção correta. A A anonimização e a impossibilidade de reconhecimento da vítima são condições eticamente indispensáveis para a utilização de imagens necroscópicas, inclusive para fins didáticos ou acadêmicos. B A oposição formalmente manifestada da família à necropsia médico-legal, quando amparada em convicções religiosas e no princípio constitucional da liberdade religiosa, obsta a realização do exame, ainda que ele tenha sido solicitado por autoridade competente. C A atuação do técnico em necropsia limita-se à execução material dos procedimentos, não lhe cabendo responsabilidade ética sobre a forma como o exame é conduzido, já que a observância dos princípios éticos é atribuição exclusiva do perito médico-legista. D Em casos excepcionais, como crimes de impacto ou de grande comoção pública, a autorização judicial pode desatender momentaneamente as normas éticas na execução das atividades de necropsia, visando oferecer uma resposta rápida, concisa e eficaz à sociedade.$q$,$q$Acerca dos limites éticos e legais da necropsia, assinale a opção correta. A A anonimização e a impossibilidade de reconhecimento da vítima são condições eticamente indispensáveis para a utilização de imagens necroscópicas, inclusive para fins didáticos ou acadêmicos. B A oposição formalmente manifestada da família à necropsia médico-legal, quando amparada em convicções religiosas e no princípio constitucional da liberdade religiosa, obsta a realização do exame, ainda que ele tenha sido solicitado por autoridade competente. C A atuação do técnico em necropsia limita-se à execução material dos procedimentos, não lhe cabendo responsabilidade ética sobre a forma como o exame é conduzido, já que a observância dos princípios éticos é atribuição exclusiva do perito médico-legista. D Em casos excepcionais, como crimes de impacto ou de grande comoção pública, a autorização judicial pode desatender momentaneamente as normas éticas na execução das atividades de necropsia, visando oferecer uma resposta rápida, concisa e eficaz à sociedade.$q$,'A',1,'under_review',false,false,$q$Transcrição verbatim do caderno de provas PCMG 2025 TPAG (Eixo Específico, fileId 1LCcKes6g5jsuLiDWpIDVRbe5t5mo0pb4); gabarito conferido em Gabarito definitivo Eixo Específico (fileId 1RjFl31pu_gjWtqu0teqVqpmtP9NraO1D).$q$)
), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Civil de Minas Gerais' and role_name='Técnico-Assistente da Polícia Civil e de Atividades Governamentais (TPAG) - Auxiliar de Perícia' and contest_year=2025
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=(
    case
      when imported.item_number between 1 and 15 then 'Prova objetiva PCMG 2025 TPAG - Eixo Geral'
      when imported.item_number between 16 and 30 then 'Prova objetiva PCMG 2025 TPAG - Eixo Legislação'
      else 'Prova objetiva PCMG 2025 TPAG - Eixo Específico'
    end
  )
  join public.content_sources answer_source on answer_source.title=(
    case
      when imported.item_number between 1 and 15 then 'Gabarito definitivo PCMG 2025 TPAG - Eixo Geral'
      when imported.item_number between 16 and 30 then 'Gabarito definitivo PCMG 2025 TPAG - Eixo Legislação'
      else 'Gabarito definitivo PCMG 2025 TPAG - Eixo Específico'
    end
  )
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Civil de Minas Gerais','Técnico-Assistente da Polícia Civil e de Atividades Governamentais (TPAG) - Auxiliar de Perícia','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
